    ) -> Result<ToolOutput, ToolError> {
        ctx.actions().escalate();
        Ok(ToolOutput::new(serde_json::json!({"escalated": true})))
    }
}

/// Defers every call to tool `b`; allows the rest.
pub struct DeferB;

