        let item = message(vec![ContentPart::Text { text: "hi".into() }, data()]);
        assert_eq!(assistant_text(&item), Some("hi".to_owned()));
    }

    #[test]
    fn empty_message_keeps_an_empty_text() {
        assert_eq!(assistant_text(&message(vec![])), Some(String::new()));
    }
}
